import{_ as a,H as i,f as t,i as s}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"34 | CrawlerVSFuzzing：DAST与机器学习","description":"","frontmatter":{},"headers":[{"level":2,"title":"Crawler VS Fuzzing","slug":"crawler-vs-fuzzing","link":"#crawler-vs-fuzzing","children":[]},{"level":2,"title":"Crawler 网络爬虫","slug":"crawler-网络爬虫","link":"#crawler-网络爬虫","children":[]},{"level":2,"title":"Fuzzing 模糊测试","slug":"fuzzing-模糊测试","link":"#fuzzing-模糊测试","children":[]},{"level":2,"title":"实战部分","slug":"实战部分","link":"#实战部分","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Web漏洞挖掘实战/34｜CrawlerVSFuzzing：DAST与机器学习.md","filePath":"Web漏洞挖掘实战/34｜CrawlerVSFuzzing：DAST与机器学习.md","lastUpdated":1795536081000}'),n={name:"Web漏洞挖掘实战/34｜CrawlerVSFuzzing：DAST与机器学习.md"};function l(r,e,p,h,o,g){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="_34-crawlervsfuzzing-dast与机器学习" tabindex="-1">34 | CrawlerVSFuzzing：DAST与机器学习 <a class="header-anchor" href="#_34-crawlervsfuzzing-dast与机器学习" aria-label="Permalink to &quot;34 | CrawlerVSFuzzing：DAST与机器学习&quot;">​</a></h1><p>你好，我是王昊天。</p><p>经过之前的学习，相信你已经对 Web 漏洞挖掘的基础知识有了一定的理解。其中，我们学习了多种 Web 漏洞攻击方式，例如 SQL 注入以及 SSRF 攻击。事实上，网络攻防与战争是类似的。攻击者就好像侵略者一样想要通过攻击行为去获取一些资源或者满足自己的目的，而Web 应用开发者则像抵抗军一样去尽力守护自己的城市。</p><p>我对战争也有一定的研究，在八国联军侵略祖国时，我们对敌军飞机的进攻束手无策，只有在看到它之后使用手枪尝试发射子弹击落它们。这无论是对敌人的侦查以及攻击方式都是不够强力的。当我们祖国富强之后，有了雷达探测以及导弹系统，就能及时发现敌人的飞机并将它们击落。其实，在网络攻防中也存在类似于雷达、导弹一样的工具，它们为 Crawler 与Fuzzing，这一讲就让我们一起学习它吧！</p><h2 id="crawler-vs-fuzzing" tabindex="-1">Crawler VS Fuzzing <a class="header-anchor" href="#crawler-vs-fuzzing" aria-label="Permalink to &quot;Crawler VS Fuzzing&quot;">​</a></h2><p>Crawler 即网络爬虫，我们可以利用它来爬取一些自己想要的数据，例如豆瓣网的评分以及财经网的股市信息等。在网络攻防中它还具有另一个作用，我们可以用它来爬取待攻击页面的所有链接，这样就可以扩充我们的攻击目标，使我们不仅对当前页面发起攻击，还可以对其相关的页面进行攻击。所以，我们说 Crawler 就像个雷达一样，它可以扫描当前页面的信息。这样，我们就能获取一些其它可供攻击的目标页面。</p><p>而 Fuzzing 即模糊测试，你可能对它较为陌生，不过请不用担心，事实上它就是一种软件测试技术，我们可以通过提供大量非预期的输入并监视异常结果来发现软件的故障，从而寻找Web 应用的漏洞。可见 Fuzzing 则像一个导弹一样，可以对页面发起强有力的攻击行为。</p><p>接下来，我们将具体学习一下它们。首先，我们来学习 Crawler 的相关知识。</p><h2 id="crawler-网络爬虫" tabindex="-1">Crawler 网络爬虫 <a class="header-anchor" href="#crawler-网络爬虫" aria-label="Permalink to &quot;Crawler 网络爬虫&quot;">​</a></h2><p>Crawler 网络爬虫是一种按照一定的规则，从 Web 应用中获取想要的信息的程序或脚本，我们常将它称为网页蜘蛛、网络机器人。</p><p>这么说可能有点抽象，为了让你更好地理解网络爬虫，下面我们一起看一个简单的示例。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> urllib </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> request</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(request.urlopen(request.Request(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://lev.zone/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)).read().decode(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;utf-8&quot;</span></span></code></pre></div><p>上述是一段 Python 爬虫代码，利用它我们就可以获取到潮汐社区首页的内容。运行代码获取到的输出为：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​p class=&quot;tlak_p&quot;&gt;使用潮汐时，你无需进行工具的安装或环境的配置，即可一键开启使用，在线对安全资</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">           &lt;​h5 class=&quot;mt-4&quot;&gt;自动化攻击编排&lt;​/h5&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">           &lt;​p class=&quot;tlak_p&quot;&gt;在潮汐，你可以根据接口，调用不同的安全工具，创建自动化的攻击检</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​a href=&quot;./pages/how-use.html&quot; class=&quot;text-dark icon-move-right&quot;&gt;了解更多</span></span></code></pre></div><p>由于内容太多，这里我截取了一部分输出，可以看到我们已经成功获取到了潮汐页面的内容。之后，你可以利用一些比较好用的 Python 库例如 BS4，对数据内容进行解析，提取出我们需要的数据。这样，我们无需访问页面也可以获取到页面中我们想要的信息啦。</p><p>除此之外，还有很多情况需要 Crawler 爬虫的支持。一个典型的场景为冷启动问题，例如一个社区在创立之初，它的用户数目肯定是很少的，有一些新加入的用户看到社区没什么人，很容易因此放弃使用该社区。开发者为了避免这种情况，就会使用爬虫去一些人流量较大的 Web应用例如微博，爬取一些用户的动态放到自己的社区里，这有利于构造出社区的氛围。</p><p>另一种情形为搜索引擎，如今有很多出名的搜索引擎，例如百度以及 Google。它们当中保存有很多的数据，这些数据都是通过爬虫所获取到的。总体来说，现在是一个大数据时代，我们可以通过爬虫这个低成本高收益的方式去获取想要的数据。</p><p>以上都是爬虫的通用功能，而对于攻击者而言，爬虫对我们也是有很多帮助的。当我们想要攻击一个 Web 应用时，例如 <a href="http://lev.zone" target="_blank" rel="noreferrer">http://lev.zone</a>，我们会想要获取这个 Web 页面的所有链接，这可以扩大我们的攻击面，使得我们攻击成功的概率增加。而需要做到这点，我们只需要将爬虫获取到的内容做解析，将其中 &lt;​a href=“xxx”&gt; 中的内容进行提取，就可以获取到页面的链接了。</p><p>到这里，你已经对 Crawler 网络爬虫的实现方式、原理及功能有了一定的了解。下面，让我们一起学习另一部分 Fuzzing 模糊测试的内容。</p><h2 id="fuzzing-模糊测试" tabindex="-1">Fuzzing 模糊测试 <a class="header-anchor" href="#fuzzing-模糊测试" aria-label="Permalink to &quot;Fuzzing 模糊测试&quot;">​</a></h2><p>Fuzzing 技术最早诞生于 1950 年，那时候的计算机数据主要保存在打孔卡片上，计算机程序想要对数据进行操作就需要读取这些卡片的数据进行计算和输出。</p><p>这个设想是可行的，可是有时候会有一些垃圾卡片，计算机在读取它们时会获得一些不正常的输入信息，这些偶然的错误会导致计算机程序产生错误和异常甚至崩溃，这就是 Fuzzing 最初的来历。</p><p>如今，随着计算机技术的发展，Fuzzing 技术也在不断发展，现在的 Fuzzing 是依靠计算机软件自动执行的，包括使用随机函数生成随机的测试用例，然后计算机会将这些输入发送给测试接口，并自动分析系统是否因为这些输入导致异常的发生。这种依赖于计算机的自动执行方式会使得 Fuzzing 的效率大大提升。效率的提高也使得 Fuzzing 模糊测试成为了目前最主流的漏洞挖掘方案，据了解，近年来 80% 以上的漏洞都是通过 Fuzzing 发现的。</p><p>不知道你是否还记得我们在学习 XSS 注入时，曾经学过一款名为 XSStrike 的 XSS 检测工具，事实上它就是一款典型的 Fuzzing 工具。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/34/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/34/1.png" alt=""></a></p><p>从工具的使用截图中，我们可以看到它按照一定的格式随机生成了很多的 payload，然后将它发送给我们指定的链接，并将页面的异常响应概率返回给了我们。这就是 Fuzzing 模糊测试的功能之一，其实我们还可以利用它来绕 WAF、判断 Web 应用是否有注入漏洞以及 Bug 的存在。</p><p>到这里，你已经对 Fuzzing 模糊测试有了一定的理解，接下来，让我们一起进入到实战部分，将 Crawler 以及 Fuzzing 相结合，这可以帮助你更好地理解 Crawler 与 Fuzzing 各自的作用与彼此之间的联系。</p><h2 id="实战部分" tabindex="-1">实战部分 <a class="header-anchor" href="#实战部分" aria-label="Permalink to &quot;实战部分&quot;">​</a></h2><p>从这一讲的实战部分开始，我们将会用到一个好用的安全工具网站——潮汐社区版<a href="http://lev.zone" target="_blank" rel="noreferrer">http://lev.zone</a>。它可以帮助我们解决安全工具使用的相关问题，例如安全工具的使用、更新及维护，我们利用它可以便捷地使用各种安全工具。如果你乐于分享，你也可以将自己的工具上传到其中，供其他用户使用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/34/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/34/2.png" alt=""></a></p><p>接下来，我们需要点击立即体验并注册账号，在注册过程中需要用到邀请码，你使用VefMiMj7N37tHDL7 即可，不过它仅可支持有限个用户使用。然后登录进去，就能看到很多的安全工具啦。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/34/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/34/3.png" alt=""></a></p><p>其中就包括了 Crawler 工具以及 Fuzzing 工具。不过我们在使用之前需要进行一定的配置设置。</p><p>这里需要点击网页顶栏的文档，然后选择使用说明就可以看到该应用的配置方式。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/34/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/34/4.png" alt=""></a></p><p>注意，因为我们仅仅需要使用集成好了的工具，所以我们只用按照文档完成 Docker 安装、VPN 介入凭证设置、SSH 连接配置以及 Docker-compose 启动这四步即可。完成之后，我们就可以任意使用其中的工具了。</p><p>首先，我们选择 crawler:1.0 这款工具，然后用它来创建一个任务，它可以用来爬取一个网站的所有同域名链接。</p><p>这里，我们选择谜团 <a href="http://mituan.zone" target="_blank" rel="noreferrer">http://mituan.zone</a> 中的专项·XSS 跨站脚本攻击（实战）作为靶场，将它的链接例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://be10a2b2f16548f38ed07112904ddaa8.app.mituan.zone</span></span></code></pre></div><p>输入到 crawler 工具中，点击运行，等待任务完成就会返回爬取到的链接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://be10a2b2f16548f38ed07112904ddaa8.app.mituan.zone/level1.php?name=test</span></span></code></pre></div><p>这样，我们就完成了爬虫的功能，接着，我们将爬取到的链接传递给 Fuzzing 模糊测试工具XSStrike 使用。</p><p>结合我们之前对 XSStrike 的学习，从它运行的结果来看，我们可以判断出该页面存在 XSS 注入攻击。</p><p>到这里，我们已经成功运用了 Crawler 与 Fuzzing 对一个 Web 应用发起漏洞探测。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在这一讲中，我们学习了 Crawler 网络爬虫与 Fuzzing 模糊测试。</p><p>首先，我们分析了 Crawler 网络爬虫的原理，即向 Web 应用发送请求获取响应内容，然后从响应内容中提取需要的信息。并且，我们还知道了爬虫的功能，它不仅可以用来获取信息，还可以用来解决冷启动问题。从攻击者角度来说，爬虫还可以用来扩大攻击面，让我们的思维进行扩展。</p><p>之后，我们学习了 Fuzzing 模糊测试，了解到它其实就是按照一定的规则构造随机输入，然后将输入发送给网页接口进行测试，之后根据响应结果是否有异常来判断 Web 应用是否存在与此相关的安全问题。</p><p>最后，我们利用潮汐社区版，在对该 Web 应用进行一定的配置之后，对谜团中的靶场 XSS 跨站脚本攻击（实战）发起攻击行为，先使用 Crawler 网络爬虫获取攻击页面的链接，然后将获取到的链接交给 Fuzzing 模糊测试工具 XSStrike 使用，根据结果，我们发现该靶场存在 XSS注入问题。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你认为 Fuzzing 模糊测试工具的优点有哪些？</p><p>欢迎在评论区留下你的思考。如果觉得今天的内容对你有所帮助的话，也欢迎你把课程分享给其他同事或朋友，我们共同学习进步！</p>`,52)])])}const c=a(n,[["render",l]]);export{E as __pageData,c as default};
